-- =====================================================================
-- Rabbora Living — product migration (categories, products, product_images,
-- product_variants)
-- Generated 2026-09-27 from the review spreadsheet data (rabbora-product-review.xlsx),
-- which was extracted only from the frontend JS files attached on 27 Sep 2026.
--
-- REVIEW THIS FILE BEFORE RUNNING IT. It has NOT been run on your database.
--
-- What it does:
--   * 8 categories, 158 products, 493 product images, 695 size variants.
--   * One product per unique product name. Its slug, description, images and
--     sizes come from the bed's own category page; Bed Frames, Best Sellers and
--     Rapid Delivery stay frontend collections (not categories).
--   * Every size price is the price the page itself shows (exact price list,
--     or the page's own base-price + size-difference rule where it has no list).
--   * products.price = the product's lowest size price.
--   * compare_at_price only where the page shows a crossed-out price.
--   * stock_quantity = 0 everywhere (no real stock data exists).
--   * Placeholder descriptions are stored as NULL. Nothing is invented.
--   * Not migrated: TV beds 5–12 (no images, calculated prices), rapid-14 and
--     rapid-24 (possible duplicates, calculated prices), blanket boxes (file
--     not supplied). See the 'Not migrated' and 'Needs review' lists.
--
-- Safety:
--   * One transaction: if any statement fails, nothing is saved.
--   * Safe to run again: existing rows (same slug / same product+image /
--     same product+size) are left untouched, nothing is duplicated.
--   * No category or product IDs are hard-coded; rows are found by slug.
--   * A final check stops and rolls everything back if any expected product,
--     image or size is missing, or if an existing product with one of these
--     slugs has a different name.
--   * No schema changes. No users/sessions/cart/wishlist/order tables touched.
-- =====================================================================

BEGIN;

-- ---------------------------------------------------------------------
-- 1. Categories (found again by slug; an existing slug is left as it is)
-- ---------------------------------------------------------------------
INSERT INTO categories (name, slug) VALUES
  ('Slatted Ottoman Beds', 'slatted-ottoman-beds'),
  ('Solid Base Ottomans', 'solid-base-ottomans'),
  ('High Headboard Beds', 'high-headboard-beds'),
  ('TV Beds', 'tv-beds'),
  ('Storage Beds With Drawers', 'storage-drawers'),
  ('Kids’ Beds', 'kids-beds'),
  ('Luxury Mattresses', 'mattresses'),
  ('Sofas', 'sofas')
ON CONFLICT (slug) DO NOTHING;

-- ---------------------------------------------------------------------
-- 2. Products
--    (name, slug, description, price, category slug, main image)
-- ---------------------------------------------------------------------
INSERT INTO products (name, slug, description, price, category_id, main_image, stock_quantity, is_active)
