  ) AS e(slug, name, category_slug, n_images, n_variants)
  LEFT JOIN products p ON p.slug = e.slug
  LEFT JOIN categories c ON c.id = p.category_id
  WHERE p.id IS NULL
     OR p.name <> e.name
     OR c.slug IS DISTINCT FROM e.category_slug
     OR (SELECT count(*) FROM product_images pi WHERE pi.product_id = p.id) < e.n_images
     OR (SELECT count(*) FROM product_variants pv WHERE pv.product_id = p.id) < e.n_variants;

  IF problems > 0 THEN
    RAISE EXCEPTION 'Migration check failed for % product(s): a product is missing, has a different name/category, or is missing images/sizes. Nothing was saved.', problems;
  END IF;

  RAISE NOTICE 'Migration check passed: % products verified.', 158;
END $$;

